def packed(last, inspector):
    fields=[('last',last)]
    if inspector is not None:
        fields.append(('owner',inspector))
    return tuple(fields)
def unpack(ticket):
    fields=dict(ticket)
    readers=[v for k,v in ticket if k=='owner' and v is not None]
    return fields['last'],next(iter(readers),None)

