import capsule
def sample(studio, meter=None):
    active = meter if meter is not None else studio.meter()
    return capsule.encode(active.measure('start'), active)
def wake(ticket, studio):
    v, chain = capsule.decode(ticket)
    active = next((x for x in chain if x is not None), None)
    if active is None:
        active = studio.meter()
    return v, active.measure('wake')
